#
# TABLE STRUCTURE FOR: CUSTOMER
#

DROP TABLE IF EXISTS `CUSTOMER`;

CREATE TABLE `CUSTOMER` (
  `CUS_ID` int(4) NOT NULL,
  `CUS_FNAME` varchar(30) NOT NULL,
  `CUS_LNAME` varchar(30) NOT NULL,
  `CUS_EMAIL` varchar(30) NOT NULL,
  `CUS_ADDRESS` varchar(30) NOT NULL,
  PRIMARY KEY (`CUS_ID`),
  UNIQUE KEY `CUS_EMAIL` (`CUS_EMAIL`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: DIGITAL_PROD
#
DROP TABLE IF EXISTS `DIGITAL_PROD`;

CREATE TABLE `DIGITAL_PROD` (
  `PROD_ID` int(4) NOT NULL,
  `PLATFORM_ID` int(4) NOT NULL,
  `DOWNLOAD_SIZE` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`PROD_ID`),
  KEY `PLATFORM_ID` (`PLATFORM_ID`),
  CONSTRAINT `DIGITAL_PROD_ibfk_1` FOREIGN KEY (`PROD_ID`) REFERENCES `PRODUCT` (`PROD_ID`),
  CONSTRAINT `DIGITAL_PROD_ibfk_2` FOREIGN KEY (`PLATFORM_ID`) REFERENCES `PLATFORM` (`PLATFORM_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: GAME_GENRE
#

DROP TABLE IF EXISTS `GAME_GENRE`;

CREATE TABLE `GAME_GENRE` (
  `GENRE_ID` int(4) NOT NULL,
  `GENRE_NAME` varchar(30) NOT NULL,
  PRIMARY KEY (`GENRE_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: INVENTORY
#

DROP TABLE IF EXISTS `INVENTORY`;

CREATE TABLE `INVENTORY` (
  `PROD_ID` int(4) NOT NULL,
  `QTY_AVAILABLE` int(5) NOT NULL,
  `LAST_UPDATED` date DEFAULT NULL,
  PRIMARY KEY (`PROD_ID`),
  CONSTRAINT `INVENTORY_ibfk_1` FOREIGN KEY (`PROD_ID`) REFERENCES `PRODUCT` (`PROD_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: INVOICE
#

DROP TABLE IF EXISTS `INVOICE`;

CREATE TABLE `INVOICE` (
  `INV_ID` int(4) NOT NULL,
  `INV_DATE` date NOT NULL,
  `INV_TOTAL` decimal(8,2) DEFAULT NULL,
  `CUS_ID` int(4) NOT NULL,
  PRIMARY KEY (`INV_ID`),
  KEY `CUS_ID` (`CUS_ID`),
  CONSTRAINT `INVOICE_ibfk_1` FOREIGN KEY (`CUS_ID`) REFERENCES `CUSTOMER` (`CUS_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: INVOICE_ITEM
#

DROP TABLE IF EXISTS `INVOICE_ITEM`;

CREATE TABLE `INVOICE_ITEM` (
  `INV_ITEM_ID` int(4) NOT NULL,
  `QUANTITY` int(5) NOT NULL,
  `PRICE` decimal(8,2) NOT NULL,
  `INV_ID` int(4) NOT NULL,
  `PROD_ID` int(4) NOT NULL,
  PRIMARY KEY (`INV_ITEM_ID`),
  KEY `INV_ID` (`INV_ID`),
  KEY `PROD_ID` (`PROD_ID`),
  CONSTRAINT `INVOICE_ITEM_ibfk_1` FOREIGN KEY (`INV_ID`) REFERENCES `INVOICE` (`INV_ID`),
  CONSTRAINT `INVOICE_ITEM_ibfk_2` FOREIGN KEY (`PROD_ID`) REFERENCES `PRODUCT` (`PROD_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: PAYMENT
#

DROP TABLE IF EXISTS `PAYMENT`;

CREATE TABLE `PAYMENT` (
  `PAYMENT_ID` int(4) NOT NULL,
  `PAYMENT_TYPE` varchar(15) DEFAULT NULL,
  `PAYMENT_DATE` date NOT NULL,
  `PAYMENT_AMOUNT` decimal(8,2) NOT NULL,
  `INV_ID` int(4) NOT NULL,
  PRIMARY KEY (`PAYMENT_ID`),
  KEY `INV_ID` (`INV_ID`),
  CONSTRAINT `PAYMENT_ibfk_1` FOREIGN KEY (`INV_ID`) REFERENCES `INVOICE` (`INV_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: PHYSICAL_PROD
#

DROP TABLE IF EXISTS `PHYSICAL_PROD`;

CREATE TABLE `PHYSICAL_PROD` (
  `PROD_ID` int(4) NOT NULL,
  `SHIPPING_WEIGHT` decimal(10,2) DEFAULT NULL,
  PRIMARY KEY (`PROD_ID`),
  CONSTRAINT `PHYSICAL_PROD_ibfk_1` FOREIGN KEY (`PROD_ID`) REFERENCES `PRODUCT` (`PROD_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: PLATFORM
#

DROP TABLE IF EXISTS `PLATFORM`;

CREATE TABLE `PLATFORM` (
  `PLATFORM_ID` int(4) NOT NULL,
  `PLATFORM_NAME` varchar(20) NOT NULL,
  PRIMARY KEY (`PLATFORM_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: PRODUCT
#

DROP TABLE IF EXISTS `PRODUCT`;

CREATE TABLE `PRODUCT` (
  `PROD_ID` int(4) NOT NULL,
  `PROD_NAME` varchar(20) NOT NULL,
  `PROD_PRICE` decimal(6,2) NOT NULL,
  `VENDOR_ID` int(4) NOT NULL,
  `CAT_ID` int(4) NOT NULL,
  PRIMARY KEY (`PROD_ID`),
  KEY `VENDOR_ID` (`VENDOR_ID`),
  KEY `CAT_ID` (`CAT_ID`),
  CONSTRAINT `PRODUCT_ibfk_1` FOREIGN KEY (`VENDOR_ID`) REFERENCES `VENDOR` (`VENDOR_ID`),
  CONSTRAINT `PRODUCT_ibfk_2` FOREIGN KEY (`CAT_ID`) REFERENCES `CATEGORY` (`CAT_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



