#
# TABLE STRUCTURE FOR: SUBSCRIPTION_PROD
#

DROP TABLE IF EXISTS `SUBSCRIPTION_PROD`;

CREATE TABLE `SUBSCRIPTION_PROD` (
  `PROD_ID` int(4) NOT NULL,
  `DURATION` varchar(15) DEFAULT NULL,
  `SUB_TYPE` varchar(15) DEFAULT NULL,
  PRIMARY KEY (`PROD_ID`),
  CONSTRAINT `SUBSCRIPTION_PROD_ibfk_1` FOREIGN KEY (`PROD_ID`) REFERENCES `PRODUCT` (`PROD_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: VENDOR
#

DROP TABLE IF EXISTS `VENDOR`;

CREATE TABLE `VENDOR` (
  `VENDOR_ID` int(4) NOT NULL,
  `VENDOR_NAME` varchar(20) NOT NULL,
  `VENDOR_PHONE` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`VENDOR_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

